window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8203aba9d49a6067"]={"versions": [{"id": "FIG-8203aba9d49a6067", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm eines Testaufbaus (Systemtest-Architektur) für die AUTOSAR Adaptive Platform (ARA::PER / Persistency). Das Diagramm stellt zwei physische bzw. logische Rechnersysteme („ECU1“ als Testobjekt und „Jenkins“ als Testautomatisierungs-Host / PC) und deren Software- sowie Hardware-Schichten inklusive Testkontrollfluss und Persistenzpfad dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich in zwei Hauptstränge:</p>\n<ul class=\"fig-list\"><li><strong>ECU1 (Target):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>Persistency Test Application</code> (PTA) in einer Testbox.\n</li><li>Middleware-Schicht: <code>ARA::PER / ARA::COM</code> (rot hinterlegt).\n</li><li>Plattformbibliotheken: <code>POSIX libs (libc, ...)</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>Intel Minnowboard</code> mit integriertem persistentem Speicherblock <code>Nonvolatile Memory</code>.\n</li></ul>\n</li><li><strong>Jenkins (Host / PC):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>Persistency Tester</code>.\n</li><li>Ausführungsebene: <code>Jenkins</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>PC</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Interner Persistenzpfad von <code>Persistency Test Application</code> durch <code>ARA::PER / ARA::COM</code> und <code>POSIX libs (libc, ...)</code> über das OS in das <code>Nonvolatile Memory</code>.\n</li><li>Externer Rückmelde- und Synchronisationspfad von <code>Intel Minnowboard</code> über Hardware-Verbindung zum <code>PC</code>, weiter über <code>Jenkins</code> zum <code>Persistency Tester</code> und zurück zur <code>Persistency Test Application</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert einen geschlossenen Teststeuerungs- und Verifikationszyklus mittels gestrichelter roter Pfeile:</p>\n<ol class=\"fig-list\"><li>Schreib-/Lesezugriff: Die <code>Persistency Test Application</code> greift über die AUTOSAR-Adaptive-Laufzeitumgebung (<code>ARA::PER / ARA::COM</code>) und die darunterliegenden <code>POSIX libs</code> sowie das Realtime-Linux auf das <code>Nonvolatile Memory</code> des Intel Minnowboards zu.\n</li><li>Beobachtung/Steuerung: Daten bzw. Testergebnisse werden von der Target-Hardware (<code>Intel Minnowboard</code>) an den Host-<code>PC</code> übertragen.\n</li><li>Testauswertung: Der <code>Jenkins</code>-Server leitet die Daten an die Testinstanz <code>Persistency Tester</code> weiter.\n</li><li>Testregelung: Vom <code>Persistency Tester</code> bzw. Jenkins schließt sich die Schleife zurück zur <code>Persistency Test Application</code> auf ECU1 zur Initiierung bzw. Steuerung weiterer Testfälle.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert den beispielhaften Hardware- und Software-Prüfaufbau für Systemtests des Functional Clusters Persistency (ARA::PER) im Rahmen von AUTOSAR Adaptive. Es verdeutlicht, dass Tests auf Zielhardware (Intel Minnowboard unter RT-Linux) automatisiert über einen externen CI/CD-Server (Jenkins auf x86-PC) gesteuert und validiert werden, wobei Persistenzoperationen über POSIX-Systembibliotheken auf physischen nicht-flüchtigen Speicher durchgreifen.</p>"}, {"id": "FIG-c6879191612c46b1", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm eines Testaufbaus (Systemtest-Architektur) für die AUTOSAR Adaptive Platform (ARA::PER / Persistency). Das Diagramm stellt zwei physische bzw. logische Rechnersysteme („ECU1“ als Testobjekt und „Jenkins“ als Testautomatisierungs-Host / PC) und deren Software- sowie Hardware-Schichten inklusive Testkontrollfluss und Persistenzpfad dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich in zwei Hauptstränge:</p>\n<ul class=\"fig-list\"><li><strong>ECU1 (Target):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>Persistency Test Application</code> (PTA) in einer Testbox.\n</li><li>Middleware-Schicht: <code>ARA::PER / ARA::COM</code> (rot hinterlegt).\n</li><li>Plattformbibliotheken: <code>POSIX libs (libc, ...)</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>Intel Minnowboard</code> mit integriertem persistentem Speicherblock <code>Nonvolatile Memory</code>.\n</li></ul>\n</li><li><strong>Jenkins (Host / PC):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>Persistency Tester</code>.\n</li><li>Ausführungsebene: <code>Jenkins</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>PC</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Interner Persistenzpfad von <code>Persistency Test Application</code> durch <code>ARA::PER / ARA::COM</code> und <code>POSIX libs (libc, ...)</code> über das OS in das <code>Nonvolatile Memory</code>.\n</li><li>Externer Rückmelde- und Synchronisationspfad von <code>Intel Minnowboard</code> über Hardware-Verbindung zum <code>PC</code>, weiter über <code>Jenkins</code> zum <code>Persistency Tester</code> und zurück zur <code>Persistency Test Application</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert einen geschlossenen Teststeuerungs- und Verifikationszyklus mittels gestrichelter roter Pfeile:</p>\n<ol class=\"fig-list\"><li>Schreib-/Lesezugriff: Die <code>Persistency Test Application</code> greift über die AUTOSAR-Adaptive-Laufzeitumgebung (<code>ARA::PER / ARA::COM</code>) und die darunterliegenden <code>POSIX libs</code> sowie das Realtime-Linux auf das <code>Nonvolatile Memory</code> des Intel Minnowboards zu.\n</li><li>Beobachtung/Steuerung: Daten bzw. Testergebnisse werden von der Target-Hardware (<code>Intel Minnowboard</code>) an den Host-<code>PC</code> übertragen.\n</li><li>Testauswertung: Der <code>Jenkins</code>-Server leitet die Daten an die Testinstanz <code>Persistency Tester</code> weiter.\n</li><li>Testregelung: Vom <code>Persistency Tester</code> bzw. Jenkins schließt sich die Schleife zurück zur <code>Persistency Test Application</code> auf ECU1 zur Initiierung bzw. Steuerung weiterer Testfälle.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert den beispielhaften Hardware- und Software-Prüfaufbau für Systemtests des Functional Clusters Persistency (ARA::PER) im Rahmen von AUTOSAR Adaptive. Es verdeutlicht, dass Tests auf Zielhardware (Intel Minnowboard unter RT-Linux) automatisiert über einen externen CI/CD-Server (Jenkins auf x86-PC) gesteuert und validiert werden, wobei Persistenzoperationen über POSIX-Systembibliotheken auf physischen nicht-flüchtigen Speicher durchgreifen.</p>"}, {"id": "FIG-6fe7574ced68fed2", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm eines Testaufbaus (Systemtest-Architektur) für die AUTOSAR Adaptive Platform. Dargestellt sind zwei Rechnersysteme („ECU2“ als Target und „Jenkins“ als Testautomatisierungs-Host / PC) mit Schichtenarchitektur sowie Testkontroll- und Speicherpfaden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Teilsysteme:</p>\n<ul class=\"fig-list\"><li><strong>ECU2 (Target):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>System Test Applications</code>.\n</li><li>Middleware-Schicht: <code>ARA</code> (rot hinterlegt).\n</li><li>Plattformbibliotheken: <code>POXIS libs (libc, ...)</code> (blau hinterlegt; Tippfehler im Diagramm).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>Intel Minnowboard</code> mit Speicherelement <code>Nonvolatile memory</code>.\n</li></ul>\n</li><li><strong>Jenkins (Host / PC):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>Persistency Tester</code>.\n</li><li>Ausführungsumgebung: <code>Jenkins</code> (blau hinterlegt, vergrößerter Block).\n</li><li>Betriebssystem: <code>Linux</code>.\n</li><li>Hardware-Basis: <code>PC</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Lokaler Schreibpfad von <code>System Test Applications</code> über <code>ARA</code> und <code>POXIS libs</code> via OS auf <code>Nonvolatile memory</code>.\n</li><li>Test- und Rückführungs-Schleife (gestrichelte rote Pfeile) zwischen <code>Intel Minnowboard</code>, <code>PC</code>, <code>Jenkins</code>, <code>Persistency Tester</code> und <code>System Test Applications</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Testausführung: <code>System Test Applications</code> triggert Persistenzoperationen über das Adaptive Runtime Interface (<code>ARA</code>) und POSIX-Bibliotheken in das nicht-flüchtige Speichermedium (<code>Nonvolatile memory</code>) des Intel Minnowboards.\n</li><li>Messwert-/Statusübertragung: Von der Zielhardware (<code>Intel Minnowboard</code>) führt der Kommunikationspfad zum Host-<code>PC</code>.\n</li><li>Testorchestration: <code>Jenkins</code> nimmt die Daten entgegen und speist sie in den <code>Persistency Tester</code> ein.\n</li><li>Rückkopplung: Die Testschleife schließt sich zurück zur Applikation auf ECU2 zur Fortführung oder Auswertung der Testszenarien.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht den hardwarenahen Systemtestaufbau für Adaptive-Anwendungen auf einer Referenz-ECU (Intel Minnowboard) unter Steuerung eines Continuous-Integration-Systems (Jenkins). Gegenüber Standard-POSIX-Systemen bindet die Testanwendung generisch gegen <code>ARA</code>. Der Jenkins-Host fungiert unter Standard-Linux, während auf dem Test-Target ein gepatchter Real-Time-Linux-Kernel läuft.</p>"}, {"id": "FIG-9e8b597f9e0bf947", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm eines Testaufbaus (Systemtest-Architektur) für die AUTOSAR Adaptive Platform. Dargestellt sind zwei Rechnersysteme („ECU2“ als Target und „Jenkins“ als Testautomatisierungs-Host / PC) mit Schichtenarchitektur sowie Testkontroll- und Speicherpfaden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Teilsysteme:</p>\n<ul class=\"fig-list\"><li><strong>ECU2 (Target):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>PER Test Application(s)</code>.\n</li><li>Middleware-Schicht: <code>ARA</code> (rot hinterlegt).\n</li><li>Plattformbibliotheken: <code>POSIX libs (libc, ...)</code> (blau hinterlegt; korrigierte Schreibweise).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>Intel Minnowboard</code> mit Speicherelement <code>Nonvolatile memory</code>.\n</li></ul>\n</li><li><strong>Jenkins (Host / PC):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>PER Tester</code>.\n</li><li>Ausführungsumgebung: <code>Jenkins</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux</code>.\n</li><li>Hardware-Basis: <code>PC</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Lokaler Persistenzpfad von <code>PER Test Application(s)</code> über <code>ARA</code> und <code>POSIX libs (libc, ...)</code> via OS auf <code>Nonvolatile memory</code>.\n</li><li>Testkontroll- und Synchronisationspfad (gestrichelte rote Pfeile) zwischen <code>Intel Minnowboard</code>, <code>PC</code>, <code>Jenkins</code>, <code>PER Tester</code> und <code>PER Test Application(s)</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Testausführung: <code>PER Test Application(s)</code> initiiert Schreib-/Lesezugriffe über <code>ARA</code> und <code>POSIX libs (libc, ...)</code> auf das <code>Nonvolatile memory</code> des Minnowboards.\n</li><li>Übertragung: Testergebnisse und Statusdaten fließen von der Target-Plattform (<code>Intel Minnowboard</code>) zum <code>PC</code>.\n</li><li>Testverwaltung: <code>Jenkins</code> verarbeitet die Rückmeldungen und übergibt sie an den <code>PER Tester</code>.\n</li><li>Teststeuerung: Vom <code>PER Tester</code> wird der Steuerfluss zurück zu den <code>PER Test Application(s)</code> auf ECU2 geführt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht den hardwarenahen Systemtestaufbau für Adaptive-Anwendungen auf einer Referenz-ECU (Intel Minnowboard) unter Steuerung eines Continuous-Integration-Systems (Jenkins). Gegenüber Standard-POSIX-Systemen bindet die Testanwendung generisch gegen <code>ARA</code>. Der Jenkins-Host fungiert unter Standard-Linux, während auf dem Test-Target ein gepatchter Real-Time-Linux-Kernel läuft.</p>"}, {"id": "FIG-f848f73c7160078d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm eines Testaufbaus (Systemtest-Architektur) für die AUTOSAR Adaptive Platform. Dargestellt sind zwei Rechnersysteme („ECU2“ als Target und „Jenkins“ als Testautomatisierungs-Host / PC) mit Schichtenarchitektur sowie Testkontroll- und Speicherpfaden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Teilsysteme:</p>\n<ul class=\"fig-list\"><li><strong>ECU2 (Target):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>PER Test Application(s)</code>.\n</li><li>Middleware-Schicht: <code>ARA</code> (rot hinterlegt).\n</li><li>Plattformbibliotheken: <code>POSIX libs (libc, ...)</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux with Real-time Patches</code>.\n</li><li>Hardware-Basis: <code>Hardware</code> mit Speicherelement <code>Nonvolatile memory</code>.\n</li></ul>\n</li><li><strong>Jenkins (Host / PC):</strong>\n<ul class=\"fig-list\"><li>Applikationsebene: <code>PER Tester</code>.\n</li><li>Ausführungsumgebung: <code>Jenkins</code> (blau hinterlegt).\n</li><li>Betriebssystem: <code>Linux</code>.\n</li><li>Hardware-Basis: <code>PC</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Lokaler Persistenzpfad von <code>PER Test Application(s)</code> über <code>ARA</code> und <code>POSIX libs (libc, ...)</code> via OS auf <code>Nonvolatile memory</code>.\n</li><li>Testkontroll- und Synchronisationspfad (gestrichelte rote Pfeile) zwischen der Ziel-<code>Hardware</code>, <code>PC</code>, <code>Jenkins</code>, <code>PER Tester</code> und <code>PER Test Application(s)</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Testausführung: <code>PER Test Application(s)</code> initiiert Schreib-/Lesezugriffe über <code>ARA</code> und <code>POSIX libs (libc, ...)</code> auf das <code>Nonvolatile memory</code> des Minnowboards.\n</li><li>Übertragung: Testergebnisse und Statusdaten fließen von der Target-Plattform (<code>Intel Minnowboard</code>) zum <code>PC</code>.\n</li><li>Testverwaltung: <code>Jenkins</code> verarbeitet die Rückmeldungen und übergibt sie an den <code>PER Tester</code>.\n</li><li>Teststeuerung: Vom <code>PER Tester</code> wird der Steuerfluss zurück zu den <code>PER Test Application(s)</code> auf ECU2 geführt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht den hardwarenahen Systemtestaufbau für Adaptive-Persistency-Anwendungen auf einer allgemeinen Zielhardware (<code>Hardware</code>) unter Steuerung eines Continuous-Integration-Systems (Jenkins). Die Spezifikation entkoppelt den Testaufbau damit von konkreten Evaluierungsboards hin zu hardwareunabhängigen ECU-Setups unter Real-Time-Linux.</p>"}], "trans": [{"from": "FIG-8203aba9d49a6067", "to": "FIG-c6879191612c46b1", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die linke obere Ecke enthält versehentlichen Textmüll aus dem Dokumentkontext („the PTA and vice versa.“).\n</li></ul>"}, {"from": "FIG-c6879191612c46b1", "to": "FIG-6fe7574ced68fed2", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der Dokument-Textrest in der linken oberen Ecke wurde entfernt.\n</li><li>Die ECU-Bezeichnung wurde von „ECU1“ in „ECU2“ geändert.\n</li><li>Die Anwendungsbezeichnung wurde von „Persistency Test Application“ in „System Test Applications“ geändert.\n</li><li>Die Middleware-Schicht wurde von „ARA::PER / ARA::COM“ auf „ARA“ verkürzt.\n</li><li>Schreibfehler in der POSIX-Ebene: „POSIX libs (libc, ...)“ wurde zu „POXIS libs (libc, ...)“.\n</li><li>Das Betriebssystem des Testrechners („Jenkins“) wurde von „Linux with Real-time Patches“ zu „Linux“ vereinfacht.\n</li><li>Die Beschriftung im Speicherbaustein wurde typografisch von „Nonvolatile Memory“ auf „Nonvolatile memory“ geändert.\n</li><li>Das Gesamtdiagramm wurde in den Proportionen vertikal gestreckt.\n</li></ul>"}, {"from": "FIG-6fe7574ced68fed2", "to": "FIG-9e8b597f9e0bf947", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Anwendungsbezeichnung wurde von „System Test Applications“ zu „PER Test Application(s)“ präzisiert.\n</li><li>Der Tester-Baustein wurde von „Persistency Tester“ zu „PER Tester“ abgekürzt.\n</li><li>Der Schreibfehler in der POSIX-Schicht wurde korrigiert: „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“.\n</li></ul>"}, {"from": "FIG-9e8b597f9e0bf947", "to": "FIG-f848f73c7160078d", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Hardware-Plattform der ECU2 wurde von „Intel Minnowboard“ zu „Hardware“ verallgemeinert.\n</li></ul>"}]};
